class HttpRequestBuilder {
  private req: Partial<HttpRequest> = {};

  url(url: string) { this.req.url = url; return this; }
  method(method: string) { this.req.method = method; return this; }
  timeout(ms: number) { this.req.timeoutMs = ms; return this; }
  header(key: string, value: string) {
    this.req.headers = { ...this.req.headers, [key]: value };
    return this;
  }
  build(): HttpRequest {
    if (!this.req.url) throw new Error("url is required");
    return this.req as HttpRequest;
  }
}

// Reads like a sentence — no mystery arguments
const req = new HttpRequestBuilder()
  .url("https://api.example.com")
  .method("GET")
  .timeout(3000)
  .build();
